  pattern = /paladin/i;
  label = "paladin";
} else if (thievingLevel >= 55) {
  pattern = /knight of ardougne/i;
  label = "knight";
} else if (thievingLevel >= 40) {
  pattern = /guard/i;
  label = "guard";
} else if (thievingLevel >= 25) {
  pattern = /al-kharid warrior/i;
  label = "warrior";
} else {
